var e={"devices.feature.title":`Geräte`,"devices.feature.desc":`Claude nutzt deine eigenen Computer und Handys: Es sieht ihren Bildschirm, klickt, tippt und öffnet Apps. Du schaust zu und übernimmst jederzeit.`,"devices.feature.enable":`Meine Geräte nutzen`,"devices.feature.enableDesc":`Verbinde einen Computer (Windows, Mac, Linux) oder ein Android-Handy mit der App Harness Link. Sitzungen sehen die Geräte, die du erlaubst; ein Agent nur die, die du für ihn freigibst.`,"devices.openPage":`Geräte öffnen`,"devices.openPageHint":`Füge ein Gerät hinzu und wähle, was Claude darauf tun darf.`,"devices.settingsDesc":`Deine Computer und Handys, die Claude nutzen darf`,"devices.add":`Gerät hinzufügen`,"devices.add.desc":`Führe den Befehl auf dem Computer aus oder öffne den Link auf dem Handy. Der Code gilt einmal, für 15 Minuten.`,"devices.add.windows":`Windows`,"devices.add.mac":`Mac`,"devices.add.linux":`Linux`,"devices.add.android":`Android`,"devices.add.cmdWindows":`Öffne auf dem PC PowerShell (Startmenü, PowerShell eingeben) und füge ein:`,"devices.add.cmdMac":`Öffne auf dem Mac das Terminal (Spotlight, Terminal eingeben) und füge ein:`,"devices.add.cmdLinux":`Öffne ein Terminal und füge ein. X11 funktioniert vollständig; ein Wayland-Desktop wird noch nicht unterstützt (wähle beim Anmelden eine X11-Sitzung).`,"devices.add.macHelp":`macOS erteilt Bildschirmaufnahme und Bedienungshilfen der Terminal-App, nicht Harness Link: Aktiviere Terminal (oder iTerm...) in Systemeinstellungen -> Datenschutz & Sicherheit bei beiden, beende es (cmd+Q), öffne es erneut und gib harness-link ein.`,"devices.add.phone":`Scanne diesen Code mit der Handykamera. Auf der Seite: Lade die App herunter, installiere sie und tippe dann auf "In Harness Link öffnen".`,"devices.add.phoneHelp":`Harness Link bittet dich anschließend, seinen Bedienungshilfen-Dienst zu aktivieren: So sieht es den Bildschirm und tippt für Claude.`,"devices.add.apk":`App herunterladen (APK)`,"devices.add.apkHelp":`Keine Kamera zur Hand? Die Schaltfläche unter dem Code lädt die App direkt herunter: Öffne diese Seite auf dem Handy und tippe darauf, oder kopiere die Datei aufs Handy.`,"devices.add.manual":`Oder gib diese in Harness Link ein:`,"devices.add.server":`Server`,"devices.add.code":`Code`,"devices.add.secret":`Der Befehl enthält einen Code: Gib ihn nicht weiter.`,"devices.add.expires":`Läuft in {time} ab`,"devices.add.expired":`Dieser Code ist abgelaufen.`,"devices.add.again":`Neuer Code`,"devices.add.waiting":`Warte auf das Gerät…`,"devices.add.ready":`{name} ist verbunden`,"devices.add.readyDesc":`Akzeptiert. Claude kann diesen Computer nutzen, solange Harness Link in seinem Terminalfenster läuft. Wähle in seiner Zeile Nur ansehen oder Steuern.`,"devices.add.readyPhone":`Akzeptiert. Claude kann dieses Handy nutzen, solange Harness Link aktiv ist. Wähle in seiner Zeile Nur ansehen oder Steuern.`,"devices.add.done":`Fertig`,"devices.live.screen":`Bildschirm`,"devices.live.screenHelp":`Der Bildschirm, den Claude auf diesem Computer sieht und nutzt und den Zuschauen zeigt. Claude kann ihn auch selbst wechseln, wenn es einen anderen braucht.`,"devices.live.main":`Hauptbildschirm`,"devices.add.notAvailable":`Harness Link steht auf diesem Server noch nicht zum Download bereit.`,"devices.new.title":`Neues Gerät: {name} ({os})`,"devices.new.desc":`Es hat einen deiner Codes von {ip} aus verwendet. Ist es deins? Claude kann es erst nutzen, wenn du es akzeptierst. Wenn du es nicht kennst, lehne es ab: Es wird getrennt und vergisst diesen Server.`,"devices.accept":`Akzeptieren`,"devices.refuse":`Ablehnen`,"devices.empty":`Noch kein Gerät. Füge deinen Computer oder dein Handy hinzu: Claude kann dann deren Apps nutzen.`,"devices.online":`Online`,"devices.offline":`Offline · zuletzt gesehen {ago}`,"devices.paused":`Auf dem Gerät pausiert`,"devices.human":`Du hast die Kontrolle`,"devices.claude":`Claude nutzt es`,"devices.mode.label":`Was Claude tun darf`,"devices.mode.view":`Nur ansehen`,"devices.mode.control":`Steuern`,"devices.mode.viewDesc":`Claude sieht sich den Bildschirm an und führt dich an; es klickt und tippt nie.`,"devices.access.label":`Wer es nutzen darf`,"devices.access.all":`Alle Projekte und Agenten`,"devices.access.some":`Ausgewählte Projekte`,"devices.access.none":`Vorerst niemand`,"devices.access.count":`{count} Projekte`,"devices.access.count#one":`{count} Projekt`,"devices.access.agentsNote":`Ein Agent braucht das Gerät außerdem in seinen eigenen Einstellungen freigegeben (Agentenseite -> Geräte).`,"devices.watch":`Zuschauen`,"devices.rename":`Umbenennen`,"devices.rename.title":`Gerät umbenennen`,"devices.remove":`Entfernen`,"devices.remove.title":`{name} entfernen?`,"devices.remove.desc":`Claude kann es nicht mehr verwenden. Harness Link vergisst dort diesen Server und beendet sich.`,"devices.note":`Das Gerät meldet: {note}`,"devices.add.after":`Harness Link läuft in diesem Fenster und zeigt, was Claude macht. Danach gibst du harness-link in einem Terminal ein: Claude kann den Computer nur nutzen, solange dieses Fenster geöffnet ist (Ctrl+C beendet es).`,"devices.offlineHelp":`Damit Claude es nutzen kann, gib harness-link in einem Terminal auf dem Gerät ein.`,"devices.offlineHelp.android":`Damit Claude es nutzen kann, öffne Harness Link auf dem Telefon.`,"devices.outdated":`Es gibt ein neueres Harness Link ({version}): Füge das Gerät erneut hinzu, um es zu aktualisieren.`,"devices.actions.title":`Letzte Aktionen`,"devices.more":`Mehr`,"devices.list.title":`Deine Geräte`,"devices.list.count":`Deine Geräte ({count})`,"devices.actions.desc":`Was Claude auf deinen Geräten getan hat. Getippter Text wird nie gespeichert, nur seine Länge.`,"devices.actions.removed":`Entferntes Gerät`,"devices.actions.more":`Mehr anzeigen`,"devices.actions.less":`Weniger anzeigen`,"devices.act.click":`Klick bei {x}, {y}`,"devices.act.double":`Doppelklick bei {x}, {y}`,"devices.act.type":`{count} Zeichen getippt`,"devices.act.type#one":`{count} Zeichen getippt`,"devices.act.key":`{keys} gedrückt`,"devices.act.open":`App geöffnet`,"devices.act.openNamed":`{name} geöffnet`,"devices.act.wait":`{s} s gewartet`,"devices.act.screen":`Zu Bildschirm {n} gewechselt`,"devices.act.screenshot":`Bildschirm angesehen`,"devices.act.zoom":`Herangezoomt`,"devices.act.scroll":`Gescrollt`,"devices.act.drag":`Gezogen`,"devices.act.move":`Zeiger bewegt`,"devices.act.long_press":`Langer Druck`,"devices.act.ui_tree":`Elemente des Bildschirms gelesen`,"devices.act.tap_element":`Element angetippt`,"devices.act.set_text":`Feld ausgefüllt`,"devices.act.apps":`Apps aufgelistet`,"devices.act.ask_human":`Dich um einen Schritt gebeten`,"devices.act.devices":`Geräte aufgelistet`,"devices.live.title":`{name} live`,"devices.live.desc":`Der Bildschirm des Geräts, live. Berühre ihn, um zu übernehmen; gib die Kontrolle mit einem Wort an Claude zurück.`,"devices.live.take":`Übernehmen`,"devices.live.handBack":`Zurückgeben`,"devices.live.word":`Ein Wort für Claude (optional)`,"devices.live.done":`Erledigt, zurückgeben`,"devices.live.skip":`Diesen Schritt überspringen`,"devices.live.youHave":`Du hast die Kontrolle über das Gerät: Claude wartet, bis du sie zurückgibst.`,"devices.live.claudeHas":`Claude nutzt es gerade. Berühre das Bild, um zu übernehmen.`,"devices.live.viewOnly":`Nur ansehen: Claude schaut zu, er handelt nicht.`,"devices.live.offline":`Das Gerät ist offline: Harness Link läuft dort nicht, oder das Gerät schläft.`,"devices.live.paused":`Harness Link ist auf dem Gerät pausiert.`,"devices.live.connecting":`Verbindung wird hergestellt…`,"devices.live.back":`Zurück`,"devices.live.home":`Start`,"devices.live.recents":`Zuletzt verwendete Apps`,"devices.live.type":`Hier tippen, Enter sendet`,"devices.live.close":`Schließen`,"devices.live.ask":`Claude fragt dich: {message}`,"devices.bar.using":`Claude nutzt {name}`,"devices.bar.watch":`Zusehen`,"devices.ask.title":`{name}: Claude braucht dich.`,"devices.ask.open":`Öffnen`,"devices.ask.skip":`Überspringen`,"devices.agent.title":`Geräte`,"devices.agent.none":`Noch kein Gerät erlaubt das Projekt dieses Agents (Einstellungen -> Geräte -> Wer es nutzen darf).`,"devices.agent.hint":`Die Geräte, die dieser Agent nutzen darf. Standardmäßig gesperrt.`};export{e as default};